content.solution_code:
class MagicOrb {
    #mana;

    constructor() {
        this.#mana = 0;
    }

    charge(amount) {
        if (typeof amount !== 'number' || amount <= 0) {
            throw new Error("Charge amount must be a positive number.");
        }
        this.#mana += amount;
        return `Mana charged. Current mana: ${this.getManaAmount()}`;
    }

    castSpell(cost) {
        if (typeof cost !== 'number' || cost <= 0) {
            throw new Error("Spell cost must be a positive number.");
        }
        if (this.#mana < cost) {
            throw new Error("Not enough mana to cast this spell.");
        }
        this.#mana -= cost;
        return `Spell cast. Current mana: ${this.getManaAmount()}`;
    }

    getManaAmount() {
        return this.#mana;
    }
}

